              <!-- Items mini list -->
              <div style="max-height: 240px; overflow-y: auto; display: flex; flex-direction: column; gap: 0.75rem; margin-bottom: 1.5rem; padding-right: 0.5rem;">
                ${r.map(a=>`
                  <div style="display: flex; justify-content: space-between; align-items: center; font-size: 0.85rem; border-bottom: 1px solid var(--border-subtle); padding-bottom: 0.5rem;">
                    <div style="display: flex; align-items: center; gap: 0.75rem;">
                      <img src="${a.image}" alt="${a.name}" style="width: 40px; height: 40px; border-radius: var(--radius-sm); object-fit: cover;" />
                      <div>
                        <div style="font-weight: 600; color: #fff; max-width: 180px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${a.name}</div>
                        <div style="font-size: 0.75rem; color: var(--gold-dark);">${a.selectedSize} × ${a.quantity}</div>
                      </div>
                    </div>
                    <div style="font-weight: 700; color: var(--gold-bright);">${Ie(a.price*a.quantity)}</div>
                  </div>
                `).join("")}
              </div>

